package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen3Test {

    @Test
    public void testAbbreviate_NullString() {
        assertNull(WordUtils.abbreviate(null, 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_EmptyString() {
        assertEquals("", WordUtils.abbreviate("", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_UpperIsNegativeOne() {
        // upper == -1 -> upper becomes str.length()
        // index of space is -1
        // upper == str.length() -> no appendToEnd
        assertEquals("Hello World", WordUtils.abbreviate("Hello World", 0, -1, "..."));
    }

    @Test
    public void testAbbreviate_UpperGreaterThanLength() {
        // upper > str.length() -> upper becomes str.length()
        assertEquals("Hello World", WordUtils.abbreviate("Hello World", 0, 50, "..."));
    }

    @Test
    public void testAbbreviate_UpperLessThanLower() {
        // upper < lower -> upper becomes lower
        // str="Hello", lower=4, upper=2 -> upper becomes 4
        // index of space is -1
        // upper (4) != str.length (5) -> appendToEnd
        assertEquals("Hell...", WordUtils.abbreviate("Hello", 4, 2, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInString_AndAbbreviates() {
        // index == -1
        // upper (3) != str.length (5) -> appendToEnd
        assertEquals("Hel...", WordUtils.abbreviate("Hello", 0, 3, "..."));
    }

    @Test
    public void testAbbreviate_NoSpaceInString_NoAbbreviation() {
        // index == -1
        // upper (5) == str.length (5) -> no appendToEnd
        assertEquals("Hello", WordUtils.abbreviate("Hello", 0, 5, "..."));
    }

    @Test
    public void testAbbreviate_SpaceFound_AfterUpper() {
        // index of space is 6
        // index (6) > upper (4)
        // result = substring(0, 4) + appendToEnd
        assertEquals("Hell...", WordUtils.abbreviate("Hello World", 0, 4, "..."));
    }

    @Test
    public void testAbbreviate_SpaceFound_BeforeUpper() {
        // index of space is 5
        // index (5) <= upper (10)
        // result = substring(0, 5) + appendToEnd
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 10, "..."));
    }

    @Test
    public void testAbbreviate_NullAppendToEnd() {
        // Test branch where appendToEnd is null (StringUtils.defaultString handles it)
        // index of space is 6, 6 > 4
        assertEquals("Hell", WordUtils.abbreviate("Hello World", 0, 4, null));
    }

    @Test
    public void testAbbreviate_LowerBoundaryCheck() {
        // Testing the 'lower' parameter in indexOf
        // "a b c", lower=2. indexOf(" ", 2) finds space at index 4
        // index (4) > upper (3)
        assertEquals("a b", WordUtils.abbreviate("a b c", 2, 3, "..."));
    }
}
